['def run(context):', "    expected_freshness = context.get('expected_freshness')", '    freshness_status = {}', '    for key, latest_date in context.items():', "        if key.startswith('latest_'):", '            freshness_status[key] = (latest_date -> expected_freshness)', "            # Ensure dates are 'fresh' compared to 'expected_freshness'", "    return {'freshness_status': freshness_status}"]